1	// Command payflow is the 链上支付与结算编排平台 entry point.
2	package main
3	
4	import (
5		"bytes"
6		"encoding/json"
7		"flag"
8		"fmt"
9		"io"
10		"os"
11	
12		"github.com/gzhysuiioo/payflow-settlement/payflow"
13	)
14	
15	func main() {
16		os.Exit(runCLI(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
17	}
18	
19	const versionString = "payflow 0.2.0"
20	
21	func runCLI(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
22		if len(args) == 0 {
23			return runDemo(stdout)
24		}
25		switch args[0] {
26		case "demo":
27			return runDemo(stdout)
28		case "version":
29			fmt.Fprintln(stdout, versionString)
30			return 0
31		case "help", "-h", "--help":
32			usage(stdout)
33			return 0
34		case "init":
35			return cmdInit(args[1:], stdin, stdout, stderr)
36		case "submit":
37			return cmdSubmit(args[1:], stdin, stdout, stderr)
38		case "refund":
39			return cmdRefund(args[1:], stdin, stdout, stderr)
40		case "query":
41			return cmdQuery(args[1:], stdout, stderr)
42		case "reconcile":
43			return cmdReconcile(args[1:], stdin, stdout, stderr)
44		default:
45			fmt.Fprintf(stderr, "unknown command %q\n", args[0])
46			usage(stderr)
47			return 2
48		}
49	}
50	
51	func usage(w io.Writer) {
52		fmt.Fprintln(w, "usage: payflow <command> [flags]")
53		fmt.Fprintln(w, "")
54		fmt.Fprintln(w, "commands:")
55		fmt.Fprintln(w, "  init       initialize a ledger with starting balances")
56		fmt.Fprintln(w, "  submit     submit a JSON payment batch against a ledger")
57		fmt.Fprintln(w, "  refund     submit a JSON full-refund batch against a ledger")
58		fmt.Fprintln(w, "  query      print balances, settlement and refund records of a ledger")
59		fmt.Fprintln(w, "  reconcile  reconcile an ordered JSON flow against a ledger")
60		fmt.Fprintln(w, "  demo       run the in-memory settlement demo")
61		fmt.Fprintln(w, "  version    print version")
62		fmt.Fprintln(w, "  help       show this help")
63		fmt.Fprintln(w, "")
64		fmt.Fprintln(w, "ledger flags (init/submit/refund/query/reconcile):")
65		fmt.Fprintln(w, "  -l, --ledger <path>   ledger file path (required)")
66		fmt.Fprintln(w, "  -f, --file <path>     JSON input file (init/submit/refund/reconcile; default: stdin)")
67		fmt.Fprintln(w, "")
68		fmt.Fprintln(w, "submit flags:")
69		fmt.Fprintln(w, "  --dry-run             preview settlement results without writing the ledger")
70		fmt.Fprintln(w, "")
71		fmt.Fprintln(w, "reconcile range flags (seq bounds, after < seq <= through; default: full history):")
72		fmt.Fprintln(w, "  --payment-after <n>    payment seq lower bound (exclusive)")
73		fmt.Fprintln(w, "  --payment-through <n>  payment seq upper bound (inclusive)")
74		fmt.Fprintln(w, "  --refund-after <n>     refund seq lower bound (exclusive)")
75		fmt.Fprintln(w, "  --refund-through <n>   refund seq upper bound (inclusive)")
76	}
77	
78	// initRequest 是 init 的输入：{"balances":[...]}。
79	type initRequest struct {
80		Balances []payflow.BalanceInit `json:"balances"`
81	}
82	
83	type errorEnvelope struct {
84		Error struct {
85			Kind    string `json:"kind"`
86			Message string `json:"message"`
87		} `json:"error"`
88	}
89	
90	func failEnvelope(stderr io.Writer, kind, message string) int {
91		env := errorEnvelope{}
92		env.Error.Kind = kind
93		env.Error.Message = message
94		writeJSON(stderr, env)
95		return 1
96	}
97	
98	func failWithError(stderr io.Writer, err error) int {
99		return failEnvelope(stderr, payflow.KindOf(err), err.Error())
100	}
101	
102	// writeJSON 把 v 以缩进 JSON 加末尾换行写出。任一写入返回错误、或实际写出
103	// 字节少于请求字节（短写，即使未同时返回错误），都返回错误；调用方必须据此
104	// 判定输出失败，不能再当作成功。
105	func writeJSON(w io.Writer, v any) error {
106		data, err := json.MarshalIndent(v, "", "  ")
107		if err != nil {
108			fmt.Fprintf(w, `{"error":{"kind":"storage_error","message":%q}}`+"\n", err.Error())
109			return err
110		}
111		if err := writeFull(w, data); err != nil {
112			return err
113		}
114		return writeFull(w, []byte("\n"))
115	}
116	
117	// writeFull 要求一次写完 data：短写按 io.ErrShortWrite 处理。
118	func writeFull(w io.Writer, data []byte) error {
119		n, err := w.Write(data)
120		if err != nil {
121			return err
122		}
123		if n != len(data) {
124			return io.ErrShortWrite
125		}
126		return nil
127	}
128	
129	// failOutput 报告结果输出阶段（写标准输出）的失败：错误信封只写标准错误，
130	// 不往可能已留有部分内容的标准输出再补成功响应或混入错误 JSON。
131	func failOutput(stderr io.Writer, err error) int {
132		return failEnvelope(stderr, payflow.ErrStorage, "write result to standard output: "+err.Error())
133	}
134	
135	// ledgerFlagSet 构造 -l/--ledger、-f/--file 标志。
136	func ledgerFlagSet(name string) (*flag.FlagSet, *string, *string) {
137		fs := flag.NewFlagSet(name, flag.ContinueOnError)
138		fs.SetOutput(io.Discard)
139		var ledgerPath, inputFile string
140		fs.StringVar(&ledgerPath, "ledger", "", "ledger file path")
141		fs.StringVar(&ledgerPath, "l", "", "ledger file path (shorthand)")
142		fs.StringVar(&inputFile, "file", "", "JSON input file (default stdin)")
143		fs.StringVar(&inputFile, "f", "", "JSON input file (shorthand)")
144		return fs, &ledgerPath, &inputFile
145	}
146	
147	func readInput(path string, stdin io.Reader) ([]byte, error) {
148		if path == "" {
149			return io.ReadAll(stdin)
150		}
151		return os.ReadFile(path)
152	}
153	
154	func cmdInit(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
155		fs, ledgerPath, inputFile := ledgerFlagSet("init")
156		if err := fs.Parse(args); err != nil {
157			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
158		}
159		if *ledgerPath == "" {
160			return failEnvelope(stderr, payflow.ErrInvalid, "init requires --ledger <path>")
161		}
162		raw, err := readInput(*inputFile, stdin)
163		if err != nil {
164			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
165		}
166		var req initRequest
167		dec := json.NewDecoder(bytes.NewReader(raw))
168		if err := dec.Decode(&req); err != nil {
169			return failEnvelope(stderr, payflow.ErrInvalid, "parse init JSON: "+err.Error())
170		}
171		if err := requireEOF(dec, "init"); err != nil {
172			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
173		}
174		if err := payflow.CreateLedger(*ledgerPath, req.Balances); err != nil {
175			return failWithError(stderr, err)
176		}
177		writeJSON(stdout, map[string]any{
178			"status":   "initialized",
179			"ledger":   *ledgerPath,
180			"accounts": len(req.Balances),
181		})
182		return 0
183	}
184	
185	func cmdSubmit(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
186		fs, ledgerPath, inputFile := ledgerFlagSet("submit")
187		var dryRun bool
188		fs.BoolVar(&dryRun, "dry-run", false, "preview settlement results without writing the ledger")
189		if err := fs.Parse(args); err != nil {
190			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
191		}
192		if *ledgerPath == "" {
193			return failEnvelope(stderr, payflow.ErrInvalid, "submit requires --ledger <path>")
194		}
195		raw, err := readInput(*inputFile, stdin)
196		if err != nil {
197			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
198		}
199		var batch payflow.FeeBatch
200		dec := json.NewDecoder(bytes.NewReader(raw))
201		if err := dec.Decode(&batch); err != nil {
202			return failEnvelope(stderr, payflow.ErrInvalid, "parse batch JSON: "+err.Error())
203		}
204		if err := requireEOF(dec, "submit"); err != nil {
205			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
206		}
207	
208		l, err := payflow.Open(*ledgerPath)
209		if err != nil {
210			return failWithError(stderr, err)
211		}
212		defer l.Close()
213	
214		// 即使批次内全部项都失败，也是正常的逐项结果，退出码仍为 0。
215		// --dry-run 只预测业务结果：不写入账本，输出带 dry_run:true 标记。
216		// 结果输出阶段失败（写错误或短写，含末尾换行）：退出码 1，错误信封只写
217		// 标准错误；已落账的付款不回滚，预览也保持账本不变。
218		if dryRun {
219			result, err := l.Preview(batch)
220			if err != nil {
221				return failWithError(stderr, err)
222			}
223			if err := writeJSON(stdout, result); err != nil {
224				return failOutput(stderr, err)
225			}
226			return 0
227		}
228		result, err := l.Submit(batch)
229		if err != nil {
230			return failWithError(stderr, err)
231		}
232		if err := writeJSON(stdout, result); err != nil {
233			return failOutput(stderr, err)
234		}
235		return 0
236	}
237	
238	func cmdRefund(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
239		fs, ledgerPath, inputFile := ledgerFlagSet("refund")
240		if err := fs.Parse(args); err != nil {
241			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
242		}
243		if *ledgerPath == "" {
244			return failEnvelope(stderr, payflow.ErrInvalid, "refund requires --ledger <path>")
245		}
246		raw, err := readInput(*inputFile, stdin)
247		if err != nil {
248			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
249		}
250		var batch payflow.RefundBatch
251		dec := json.NewDecoder(bytes.NewReader(raw))
252		if err := dec.Decode(&batch); err != nil {
253			return failEnvelope(stderr, payflow.ErrInvalid, "parse refund batch JSON: "+err.Error())
254		}
255		if err := requireEOF(dec, "refund"); err != nil {
256			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
257		}
258	
259		l, err := payflow.Open(*ledgerPath)
260		if err != nil {
261			return failWithError(stderr, err)
262		}
263		defer l.Close()
264	
265		// 即使批次内全部项都失败，也是正常的逐项结果，退出码仍为 0。
266		// 结果输出阶段失败（写错误或短写，含末尾换行）：退出码 1，错误信封只写
267		// 标准错误；已落账的退款不回滚，批次不会重放。
268		result, err := l.Refund(batch)
269		if err != nil {
270			return failWithError(stderr, err)
271		}
272		if err := writeJSON(stdout, result); err != nil {
273			return failOutput(stderr, err)
274		}
275		return 0
276	}
277	
278	func cmdQuery(args []string, stdout, stderr io.Writer) int {
279		fs, ledgerPath, _ := ledgerFlagSet("query")
280		if err := fs.Parse(args); err != nil {
281			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
282		}
283		if *ledgerPath == "" {
284			return failEnvelope(stderr, payflow.ErrInvalid, "query requires --ledger <path>")
285		}
286		l, err := payflow.Open(*ledgerPath)
287		if err != nil {
288			return failWithError(stderr, err)
289		}
290		defer l.Close()
291		snap, err := l.Query()
292		if err != nil {
293			return failWithError(stderr, err)
294		}
295		writeJSON(stdout, snap)
296		return 0
297	}
298	
299	func cmdReconcile(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
300		fs, ledgerPath, inputFile := ledgerFlagSet("reconcile")
301		// 序号边界：after 排除下界、through 包含上界（after < seq <= through）。
302		// 用指针区分“未提供”与显式给出的 0：未提供时由库取缺省值（下界 0、
303		// 上界为该类记录的最大成功序号）。
304		var paymentAfter, paymentThrough, refundAfter, refundThrough int64
305		fs.Int64Var(&paymentAfter, "payment-after", 0, "payment seq lower bound (exclusive)")
306		fs.Int64Var(&paymentThrough, "payment-through", 0, "payment seq upper bound (inclusive)")
307		fs.Int64Var(&refundAfter, "refund-after", 0, "refund seq lower bound (exclusive)")
308		fs.Int64Var(&refundThrough, "refund-through", 0, "refund seq upper bound (inclusive)")
309		if err := fs.Parse(args); err != nil {
310			return failEnvelope(stderr, payflow.ErrInvalid, err.Error())
311		}
312		if *ledgerPath == "" {
313			return failEnvelope(stderr, payflow.ErrInvalid, "reconcile requires --ledger <path>")
314		}
315		raw, err := readInput(*inputFile, stdin)
316		if err != nil {
317			return failEnvelope(stderr, payflow.ErrStorage, "read input: "+err.Error())
318		}
319		// 先严格解析全部输入：任一条目不合法则整次拒绝，退出码 1，不输出部分报告。
320		entries, err := payflow.ParseReconcileRequest(raw)
321		if err != nil {
322			return failWithError(stderr, err)
323		}
324	
325		bounds := payflow.ReconcileBounds{}
326		fs.Visit(func(f *flag.Flag) {
327			switch f.Name {
328			case "payment-after":
329				v := paymentAfter
330				bounds.PaymentAfter = &v
331			case "payment-through":
332				v := paymentThrough
333				bounds.PaymentThrough = &v
334			case "refund-after":
335				v := refundAfter
336				bounds.RefundAfter = &v
337			case "refund-through":
338				v := refundThrough
339				bounds.RefundThrough = &v
340			}
341		})
342	
343		l, err := payflow.Open(*ledgerPath)
344		if err != nil {
345			return failWithError(stderr, err)
346		}
347		defer l.Close()
348	
349		// 对账只读：不改余额、历史或账本文件。边界非法同样整次拒绝、不输出部分
350		// 报告；输入有差异仍是正常结果，退出码 0。
351		report, err := l.ReconcileFlowRanged(entries, bounds)
352		if err != nil {
353			return failWithError(stderr, err)
354		}
355		writeJSON(stdout, report)
356		return 0
357	}
358	
359	// requireEOF 拒绝 JSON 文档之后的尾随内容。
360	func requireEOF(dec *json.Decoder, what string) error {
361		if tok, err := dec.Token(); err != io.EOF {
362			if err == nil {
363				return fmt.Errorf("%s: unexpected trailing content after JSON document (token %v)", what, tok)
364			}
365			return fmt.Errorf("%s: %v", what, err)
366		}
367		return nil
368	}
369	
370	func runDemo(stdout io.Writer) int {
371		intents := []payflow.Intent{
372			{ID: "pay-1", Account: "aa-1", Paymaster: "pm-1", Amount: 1500, Asset: "usdc", Nonce: 1, State: "pending"},
373			{ID: "pay-2", Account: "aa-1", Paymaster: "pm-1", Amount: 900, Asset: "usdc", Nonce: 2, State: "pending"},
374		}
375		spent := map[string]bool{}
376		var settlements []payflow.Settlement
377		for _, intent := range intents {
378			settlement := payflow.Execute(intent, 30, spent, 2000)
379			settlements = append(settlements, settlement)
380			fmt.Fprintf(stdout, "intent=%s status=%s charged=%d reason=%s\n", settlement.Intent, settlement.Status, settlement.Charged, settlement.Reason)
381		}
382		duplicate := payflow.Execute(intents[0], 30, spent, 2000)
383		fmt.Fprintf(stdout, "duplicate of %s status=%s reason=%s\n", duplicate.Intent, duplicate.Status, duplicate.Reason)
384		fmt.Fprintln(stdout, "reconciliation gaps:", payflow.Reconcile(intents, settlements))
385		return 0
386	}
