13	
14	// 账本文件的保存规则集中在 saveLedger 一处：序列化 → 同目录临时文件 →
15	// fsync → 0600 → 发布 → 目录 fsync。新建账本与更新已有账本只差最后的
16	// 发布策略（publishFunc）：
17	//   - 更新已有账本用 rename 原子替换（publishReplace）；
18	//   - 新建账本用 link(2) 排他创建（publishExclusive），目标被占用即拒绝。
19	//
20	// 关键不变式：磁盘上的目标文件在任意时刻要么是完整旧内容，要么是完整
21	// 新内容（临时文件先 fsync 后发布，JSON 只写一个文档）。进程在保存期间
22	// 崩溃，重开只能看到完整的旧状态或新状态，不会出现“扣款无记录”或
23	// “记录未扣款”。
24	//
25	// 发布之前任一步失败都会清理临时文件，目标位置不留半成品；发布一旦
26	// 完成，新状态已就位，后续目录 fsync 仅尽力而为，失败不再回滚。
27	
28	// publishFunc 把已完整落盘、已 fsync 的临时文件 tmp 发布到目标 path。
29	// 返回非 nil 表示发布失败，调用方负责清理临时文件。
30	type publishFunc func(tmp, path string) error
31	
32	// saveLedger 按统一的保存规则把 v 以 JSON 单文档保存到 path：
33	//  1. 写入同目录临时文件并 fsync（stageTempFile）；
34	//  2. 由 publish 把临时文件发布到目标位置；
35	//  3. 尽力 fsync 目录，帮助发布结果跨掉电保留。
36	//
37	// 发布失败时临时文件由这里统一清理；发布成功后临时名字也已统一移除
38	// （rename 后该名字本就不存在，link 后它是同一 inode 的多余名字）。
39	func saveLedger(path string, v any, publish publishFunc) error {
40		tmpName, err := stageTempFile(path, v)
41		if err != nil {
42			return err
43		}
44		if err := publish(tmpName, path); err != nil {
45			_ = os.Remove(tmpName)
46			return err
47		}
48		_ = os.Remove(tmpName)
49		syncParentDir(path)
50		return nil
51	}
52	
53	// stageTempFile 把 v 序列化为单个 JSON 文档，完整写入 path 同目录的
54	// 临时文件，fsync 后调整为 0600（仅所有者可读写），返回临时文件路径。
55	// 此时目标位置尚未被触碰；任一步失败都清理临时文件并返回 ErrStorage。
56	func stageTempFile(path string, v any) (string, error) {
57		data, err := json.Marshal(v)
58		if err != nil {
59			return "", ledgerError(ErrStorage, "encode ledger: %v", err)
60		}
61		data = append(data, '\n')
62	
63		dir := filepath.Dir(path)
64		if err := os.MkdirAll(dir, 0o700); err != nil {
65			return "", ledgerError(ErrStorage, "create ledger directory %s: %v", dir, err)
66		}
67	
68		tmp, err := os.CreateTemp(dir, ".ledger-*.tmp")
69		if err != nil {
70			return "", ledgerError(ErrStorage, "create temp file in %s: %v", dir, err)
71		}
72		tmpName := tmp.Name()
73		removeTemp := func() { _ = os.Remove(tmpName) }
74	
75		if _, err := tmp.Write(data); err != nil {
76			_ = tmp.Close()
77			removeTemp()
78			return "", ledgerError(ErrStorage, "write temp file: %v", err)
79		}
80		if err := tmp.Sync(); err != nil {
81			_ = tmp.Close()
82			removeTemp()
83			return "", ledgerError(ErrStorage, "fsync temp file: %v", err)
84		}
85		if err := tmp.Close(); err != nil {
86			removeTemp()
87			return "", ledgerError(ErrStorage, "close temp file: %v", err)
88		}
89		if err := os.Chmod(tmpName, 0o600); err != nil {
90			removeTemp()
91			return "", ledgerError(ErrStorage, "chmod temp file: %v", err)
92		}
93		return tmpName, nil
94	}
95	
96	// syncParentDir 尽力 fsync path 的父目录，帮助已完成的发布跨掉电保留
97	// 目录项。发布完成后可能出现的两种结局（旧文件/新文件）都是完整状态，
98	// 因此这里失败不影响结果，调用方也不得因此回滚内存状态。
99	func syncParentDir(path string) {
100		if d, err := os.Open(filepath.Dir(path)); err == nil {
101			_ = d.Sync()
102			_ = d.Close()
103		}
104	}
105	
106	// publishReplace 用 rename 把临时文件原子发布到 path：目标位置已有的
107	// 内容被整体替换，读者任意时刻只能看到完整的旧版本或完整新版本。
108	// 用于更新已有账本。
109	//
110	// rename 之后新文件已完整就位。即便此后目录 fsync 失败，也不能再回滚：
111	// 回滚内存会与磁盘（已是新状态）分叉。
112	func publishReplace(tmp, path string) error {
113		if err := os.Rename(tmp, path); err != nil {
114			return ledgerError(ErrStorage, "rename into place: %v", err)
115		}
116		return nil
117	}
118	
119	// publishExclusive 用 link(2)（ATOMIC_CREATE：目标存在即失败）把临时文件
120	// 排他发布到 path，绝不覆盖任何已有路径项。用于新建账本。
121	//
122	// 这使“检查路径是否占用”和“创建账本”成为内核里的同一个原子操作：
123	//   - 普通文件、目录、损坏或空文件：EEXIST，原内容逐字节不变；
124	//   - path 上是符号链接（无论其目标存在与否、指向文件还是目录）：
125	//     link 不跟随符号链接，一律 EEXIST，链接本身与其去向保持不变，
126	//     也不会顺着悬空链接把目标文件创建出来；
127	//   - 经指向目录的符号链接访问一个尚未占用的文件位置时，目录项原本
128	//     不存在，创建照常成功。
129	//
130	// 多个进程同时初始化同一尚不存在的路径时，只有一个 link 成功；
131	// 失败者拿到 EEXIST 并清理自己的临时文件，不会触碰胜出者的文件。
132	// 由于发布用的是硬链接而非 rename，胜出者磁盘上的文件从发布那一刻起
133	// 就是已 fsync 的完整内容（临时文件与 path 指向同一个 inode），
134	// 崩溃后同样只可能看到“完整新账本”或“路径不存在”，没有半成品。
135	//
136	// path 占用时返回带 ErrExists 的账本错误；其余失败返回 ErrStorage。
137	func publishExclusive(tmp, path string) error {
138		if err := os.Link(tmp, path); err != nil {
139			if errors.Is(err, syscall.EEXIST) {
140				return ledgerError(ErrExists, "ledger already exists at %s", path)
141			}
142			return ledgerError(ErrStorage, "create ledger at %s: %v", path, err)
143		}
144		return nil
145	}
146	
147	// atomicWrite 将 v 以 JSON 原子写入 path，替换该位置的已有账本。
148	// 保存规则见 saveLedger；发布策略是 rename 原子替换（publishReplace）。
149	func atomicWrite(path string, v any) error {
150		return saveLedger(path, v, publishReplace)
151	}
152	
153	// createExclusive 在 path 处排他地创建新账本文件，绝不覆盖任何已有路径项。
154	// 保存规则见 saveLedger；发布策略是 link(2) 排他创建（publishExclusive）：
155	// 路径占用返回 ErrExists 且原内容不变，写入故障返回 ErrStorage，
156	// 两种情况下路径上都不会留下半成品。
157	func createExclusive(path string, v any) error {
158		return saveLedger(path, v, publishExclusive)
159	}
