167	// 结算之后（AfterSeq 是退款落账时结算历史的长度）。这保留了
168	// “付款 → 退款 → 再付款”的真实时间顺序，使中间余额与最终余额都可验证。
169	func validateAndReplay(initial, final map[balanceKey]int64, records []Record, refunds []RefundRecord) error {
170		// 先校验结算自身的结构不变式（余额相关的判定由后面的交错重放完成，
171		// 因为退款回收的余额允许同一笔钱被再次扣出，累计毛扣款可能超过初始余额）。
172		seen := map[string]bool{}
173		for i, r := range records {
174			if r.ID == "" {
175				return ledgerError(ErrCorrupt, "settlement %d has empty id", i)
176			}
177			if seen[r.ID] {
178				return ledgerError(ErrCorrupt, "duplicate settlement id %q", r.ID)
179			}
180			seen[r.ID] = true
181			if r.Account == "" || r.Asset == "" {
182				return ledgerError(ErrCorrupt, "settlement %q missing account or asset", r.ID)
183			}
184			if _, ok := initial[balanceKey{r.Account, r.Asset}]; !ok {
185				return ledgerError(ErrCorrupt, "settlement %q touches account/asset absent from initial balances", r.ID)
186			}
187			if r.Amount <= 0 || r.Fee < 0 || r.Charged <= 0 {
188				return ledgerError(ErrCorrupt, "settlement %q has non-positive amounts", r.ID)
189			}
190			if r.FeeBps < 0 || r.FeeBps > 10000 {
191				return ledgerError(ErrCorrupt, "settlement %q has invalid fee bps", r.ID)
192			}
193			if want := feeFor(r.Amount, r.FeeBps); want != r.Fee {
194				return ledgerError(ErrCorrupt, "settlement %q fee mismatch: file %d, want %d", r.ID, r.Fee, want)
195			}
196			if r.Charged != r.Amount+r.Fee {
197				return ledgerError(ErrCorrupt, "settlement %q charged != amount + fee", r.ID)
198			}
199			if int64(i)+1 != r.Seq {
200				return ledgerError(ErrCorrupt, "settlement %q sequence gap", r.ID)
201			}
202		}
203	
204		// 校验退款自身的不变式：字段非空、序列连续、引用的结算在退款时点已存在、
205		// 金额与去向与原结算逐字一致、每笔结算最多退回一次、退款编号全局唯一。
206		// 此外付款历史只会追加，因此按退款成功顺序（即记录顺序）看，after_seq
207		// 必须单调不减：后一笔退款落账时，已存在的结算不可能比前一笔退款时更少。
208		// 该规则针对整本账本的结算历史，与退款属于哪个账户、资产或引用哪笔付款无关。
209		seenRefund := map[string]bool{}
210		refundedBy := map[string]string{} // 结算编号 -> 首个退回它的退款编号
211		prevAfterSeq := int64(-1)
212		prevRefundID := ""
213		for i, rf := range refunds {
214			if rf.ID == "" {
215				return ledgerError(ErrCorrupt, "refund %d has empty id", i)
216			}
217			if seenRefund[rf.ID] {
218				return ledgerError(ErrCorrupt, "duplicate refund id %q", rf.ID)
219			}
220			seenRefund[rf.ID] = true
221			if rf.SettlementID == "" || rf.Reason == "" {
222				return ledgerError(ErrCorrupt, "refund %q missing settlement_id or reason", rf.ID)
223			}
224			if int64(i)+1 != rf.Seq {
225				return ledgerError(ErrCorrupt, "refund %q sequence gap", rf.ID)
226			}
227			if rf.AfterSeq < 0 || rf.AfterSeq > int64(len(records)) {
228				return ledgerError(ErrCorrupt, "refund %q references settlement outside history (after_seq=%d)", rf.ID, rf.AfterSeq)
229			}
230			if rf.AfterSeq < prevAfterSeq {
231				return ledgerError(ErrCorrupt,
232					"refund %q (seq %d) has after_seq %d, but previous refund %q (seq %d) already saw %d settlements: payment history only grows",
233					rf.ID, rf.Seq, rf.AfterSeq, prevRefundID, int64(i), prevAfterSeq)
234			}
235			prevAfterSeq = rf.AfterSeq
236			prevRefundID = rf.ID
237			var target *Record
238			for j := range records {
239				if records[j].Seq <= rf.AfterSeq && records[j].ID == rf.SettlementID {
240					target = &records[j]
241					break
242				}
243			}
244			if target == nil {
245				return ledgerError(ErrCorrupt, "refund %q references non-existent settlement %q", rf.ID, rf.SettlementID)
246			}
247			if rf.Account != target.Account || rf.Asset != target.Asset ||
248				rf.Amount != target.Amount || rf.Fee != target.Fee || rf.Charged != target.Charged {
249				return ledgerError(ErrCorrupt, "refund %q amount or destination differs from settlement %q", rf.ID, rf.SettlementID)
250			}
251			if rf.Charged <= 0 {
252				return ledgerError(ErrCorrupt, "refund %q has non-positive charged amount", rf.ID)
253			}
254			if other, dup := refundedBy[rf.SettlementID]; dup {
255				return ledgerError(ErrCorrupt, "settlement %q refunded twice: %q and %q", rf.SettlementID, other, rf.ID)
256			}
257			refundedBy[rf.SettlementID] = rf.ID
258		}
259	
260		// 按成功时间交错重放：第 s 笔结算之后落入 after_seq==s 的全部退款
261		// （退款之间按其自身序号；用分桶而非假定 after_seq 单调，以抵抗篡改数据）。
262		// net[k] 为该组合截至当前时点的“净扣款”（扣款增加、退款减少），
263		// 必须始终落在 [0, initial]，且不发生 int64 溢出。
264		buckets := make([][]int, len(records)+1) // after_seq -> refunds 下标
265		for i := range refunds {
266			buckets[refunds[i].AfterSeq] = append(buckets[refunds[i].AfterSeq], i)
267		}
268		net := make(map[balanceKey]int64)
269		for s := range records {
270			r := &records[s]
271			k := balanceKey{r.Account, r.Asset}
272			sum := net[k]
273			if r.Charged > math.MaxInt64-sum {
274				return ledgerError(ErrCorrupt, "settlement %q cumulative charges overflow int64", r.ID)
275			}
276			sum += r.Charged
277			if sum > initial[k] {
278				return ledgerError(ErrCorrupt, "settlement %q drives %s/%s negative during replay", r.ID, r.Account, r.Asset)
279			}
280			net[k] = sum
281	
282			for _, ri := range buckets[int64(s)+1] {
283				rf := &refunds[ri]
284				rk := balanceKey{rf.Account, rf.Asset}
285				cur := net[rk]
286				if rf.Charged > cur {
287					return ledgerError(ErrCorrupt, "refund %q exceeds charged amount for %s/%s at its time", rf.ID, rf.Account, rf.Asset)
288				}
289				net[rk] = cur - rf.Charged
290			}
291		}
292		// after_seq==0 的退款不可能引用任何已存在结算，前面理应已拒绝；
293		// 此处兜底，任何未被消费的退款都视为顺序损坏。
294		if len(buckets[0]) != 0 {
295			return ledgerError(ErrCorrupt, "refund %q precedes every settlement", refunds[buckets[0][0]].ID)
296		}
297	
298		// 交错重放后的末态必须与文件中的最终余额逐组合一致。
299		for k, start := range initial {
300			got := start - net[k]
301			if want, present := final[k]; !present || got != want {
302				return ledgerError(ErrCorrupt, "final balance mismatch for %s/%s: replay %d, file %v", k.account, k.asset, got, want)
303			}
304		}
305		for k := range final {
306			if _, ok := initial[k]; !ok {
307				return ledgerError(ErrCorrupt, "final balance contains %s/%s absent from initial balances", k.account, k.asset)
308			}
309		}
310		return nil
311	}
312	
313	// checksumHex 返回 data 的 sha256 十六进制摘要，作为文档完整性凭证。
314	func checksumHex(data []byte) string {
315		sum := sha256.Sum256(data)
316		return hex.EncodeToString(sum[:])
317	}
318

