38	type procResult struct {
39		exitCode int
40		stdout   string
41		stderr   string
42	}
43	
44	// runConcurrentInitProcesses 启动 n 个真实 payflow init 进程，各自持有
45	// 一份互不相同的初始余额（账户 proc-i）。所有进程先在读取 stdin 处等待，
46	// 再同时放行，最大化 init 在文件系统上的重叠窗口。
47	func runConcurrentInitProcesses(t *testing.T, bin string, n int, pathFor func(i int) string) []procResult {
48		t.Helper()
49		type proc struct {
50			cmd *exec.Cmd
51			w   *os.File
52			out bytes.Buffer
53			err bytes.Buffer
54		}
55		procs := make([]*proc, n)
56		for i := 0; i < n; i++ {
57			r, w, err := os.Pipe()
58			if err != nil {
59				t.Fatal(err)
60			}
61			p := &proc{}
62			p.cmd = exec.Command(bin, "init", "-l", pathFor(i))
63			p.cmd.Stdin = r
64			p.cmd.Stdout = &p.out
65			p.cmd.Stderr = &p.err
66			p.w = w
67			if err := p.cmd.Start(); err != nil {
68				t.Fatalf("start init process %d: %v", i, err)
69			}
70			_ = r.Close() // 父进程只需写端
71			procs[i] = p
72		}
73	
74		// 全部进程已启动并阻塞在读 stdin：同时写入各自输入并关闭管道，
75		// 让它们在同一时刻解析 JSON 并调用 CreateLedger。
76		var startWG sync.WaitGroup
77		for i, p := range procs {
78			startWG.Add(1)
79			go func(i int, p *proc) {
80				defer startWG.Done()
81				body := fmt.Sprintf(`{"balances":[{"account":"proc-%02d","asset":"usdc","balance":%d}]}`, i, 2000+i)
82				_, _ = p.w.Write([]byte(body))
83				_ = p.w.Close()
84			}(i, p)
85		}
86		startWG.Wait()
87	
88		results := make([]procResult, n)
89		var wg sync.WaitGroup
90		for i, p := range procs {
91			wg.Add(1)
92			go func(i int, p *proc) {
93				defer wg.Done()
94				err := p.cmd.Wait()
95				code := 0
96				if err != nil {
97					if ee, ok := err.(*exec.ExitError); ok {
98						code = ee.ExitCode()
99					} else {
100						t.Errorf("wait init process %d: %v", i, err)
101						code = -1
102					}
103				}
104				results[i] = procResult{exitCode: code, stdout: p.out.String(), stderr: p.err.String()}
105			}(i, p)
106		}
107		wg.Wait()
108		return results
109	}
