111	// assertCLIExactlyOneInitWinner 断言并发 init 恰好一个退出码 0 且输出
112	// initialized，其余退出码 1、stderr 为 ledger_exists、stdout 为空；
113	// 返回胜出者编号。
114	func assertCLIExactlyOneInitWinner(t *testing.T, results []procResult) int {
115		t.Helper()
116		winner := -1
117		for i, r := range results {
118			switch r.exitCode {
119			case 0:
120				if winner != -1 {
121					t.Fatalf("two init processes succeeded: %d and %d", winner, i)
122				}
123				winner = i
124				var out map[string]any
125				if err := json.Unmarshal([]byte(r.stdout), &out); err != nil || out["status"] != "initialized" {
126					t.Fatalf("winner %d stdout=%q", i, r.stdout)
127				}
128				if r.stderr != "" {
129					t.Fatalf("winner %d must not write stderr: %q", i, r.stderr)
130				}
131			case 1:
132				if r.stdout != "" {
133					t.Fatalf("loser %d must not write success output: %q", i, r.stdout)
134				}
135				var env map[string]any
136				if err := json.Unmarshal([]byte(r.stderr), &env); err != nil {
137					t.Fatalf("loser %d stderr not JSON: %q", i, r.stderr)
138				}
139				if kind := env["error"].(map[string]any)["kind"]; kind != "ledger_exists" {
140					t.Fatalf("loser %d kind=%v want ledger_exists", i, kind)
141				}
142			default:
143				t.Fatalf("process %d unexpected exit code %d: %s", i, r.exitCode, r.stderr)
144			}
145		}
146		if winner == -1 {
147			t.Fatalf("no init process succeeded")
148		}
149		return winner
150	}
