155		bin := buildPayflowBinary(t)
156		for round := 0; round < 10; round++ {
157			path := filepath.Join(t.TempDir(), "ledger.json")
158			const n = 12
159			pathFor := func(i int) string { return path }
160			results := runConcurrentInitProcesses(t, bin, n, pathFor)
161			winner := assertCLIExactlyOneInitWinner(t, results)
162	
163			r := runCLIWith(t, []string{"query", "-l", path}, "")
164			if r.code != 0 {
