169					Account string `json:"account"`
170					Balance int64  `json:"balance"`
171				} `json:"balances"`
172				Settlements []any `json:"settlements"`
173				Refunds     []any `json:"refunds"`
174			}
175			if err := json.Unmarshal([]byte(r.out), &snap); err != nil {
176				t.Fatal(err)
177			}
178			if len(snap.Balances) != 1 {
179				t.Fatalf("round %d balances=%+v want exactly the winner's one combo", round, snap.Balances)
180			}
181			if got := fmt.Sprintf("proc-%02d", winner); snap.Balances[0].Account != got ||
182				snap.Balances[0].Balance != int64(2000+winner) {
183				t.Fatalf("round %d winner balance=%+v want %s=%d",
