198			realDir := filepath.Join(base, "real")
199			if err := os.Mkdir(realDir, 0o700); err != nil {
200				t.Fatal(err)
201			}
202			linkDir := filepath.Join(base, "link")
203			if err := os.Symlink(realDir, linkDir); err != nil {
204				t.Fatal(err)
205			}
206			realPath := filepath.Join(realDir, "ledger.json")
207			linkPath := filepath.Join(linkDir, "ledger.json")
