219				t.Fatalf("round %d: directory symlink altered: %v", round, err)
220			}
221			for name, p := range map[string]string{"real": realPath, "link": linkPath} {
222				r := runCLIWith(t, []string{"query", "-l", p}, "")
223				if r.code != 0 {
