225				}
226				var snap struct {
227					Balances []struct {
228						Account string `json:"account"`
229						Balance int64  `json:"balance"`
230					} `json:"balances"`
231				}
232				if err := json.Unmarshal([]byte(r.out), &snap); err != nil {
233					t.Fatal(err)
234				}
235				if len(snap.Balances) != 1 ||
236					snap.Balances[0].Account != fmt.Sprintf("proc-%02d", winner) ||
237					snap.Balances[0].Balance != int64(2000+winner) {
238					t.Fatalf("round %d via %s balances=%+v", round, name, snap.Balances)
239				}
240			}
241		}
242	}
243	
244	// 账本文件位置是指向不存在文件的符号链接时，init 返回 ledger_exists：
245	// 不替换链接、不顺着链接创建目标，也不输出成功结果。
246	func TestCLIInitRejectsDanglingSymlink(t *testing.T) {
247		bin := buildPayflowBinary(t)
248		dir := t.TempDir()
249		target := filepath.Join(dir, "ghost-ledger.json")
250		link := filepath.Join(dir, "ledger.link")
251		if err := os.Symlink(target, link); err != nil {
252			t.Fatal(err)
253		}
254	
255		// 用分离的 stdout/stderr 断言通道与退出码。
256		var so, se bytes.Buffer
257		cmd := exec.Command(bin, "init", "-l", link)
258		cmd.Stdin = bytes.NewReader([]byte(`{"balances":[{"account":"aa","asset":"usdc","balance":1}]}`))
259		cmd.Stdout = &so
260		cmd.Stderr = &se
261		code := 0
262		if runErr := cmd.Run(); runErr != nil {
263			if ee, ok := runErr.(*exec.ExitError); ok {
264				code = ee.ExitCode()
265			} else {
266				t.Fatal(runErr)
267			}
268		}
269		if code != 1 {
270			t.Fatalf("exit code=%d want 1", code)
271		}
272		if so.String() != "" {
273			t.Fatalf("no success output allowed on occupied path: %q", so.String())
274		}
275		var env map[string]any
276		if err := json.Unmarshal(se.Bytes(), &env); err != nil ||
277			env["error"].(map[string]any)["kind"] != "ledger_exists" {
278			t.Fatalf("stderr envelope=%q", se.String())
279		}
280		if fi, err := os.Lstat(link); err != nil || fi.Mode()&os.ModeSymlink == 0 {
281			t.Fatalf("dangling symlink must remain in place: %v", err)
282		}
283		if dest, err := os.Readlink(link); err != nil || dest != target {
284			t.Fatalf("symlink destination changed: %q %v", dest, err)
285		}
286		if _, err := os.Stat(target); !os.IsNotExist(err) {
287			t.Fatalf("link target must not be created: %v", err)
288		}
289	}
290	
291	// 经目录符号链接在未占用位置 init 成功；随后的 submit/refund/query
292	// 经真实路径与符号链接路径都能正常更新和读取。
293	func TestCLIInitThroughDirSymlinkThenPaymentsAndRefunds(t *testing.T) {
294		bin := buildPayflowBinary(t)
295		base := t.TempDir()
296		realDir := filepath.Join(base, "real")
297		if err := os.Mkdir(realDir, 0o700); err != nil {
298			t.Fatal(err)
299		}
300		linkDir := filepath.Join(base, "link")
301		if err := os.Symlink(realDir, linkDir); err != nil {
302			t.Fatal(err)
303		}
304		realPath := filepath.Join(realDir, "ledger.json")
305		linkPath := filepath.Join(linkDir, "ledger.json")
306	
307		var so, se bytes.Buffer
308		cmd := exec.Command(bin, "init", "-l", linkPath)
309		cmd.Stdin = bytes.NewReader([]byte(`{"balances":[{"account":"aa","asset":"usdc","balance":1000}]}`))
310		cmd.Stdout = &so
311		cmd.Stderr = &se
312		if err := cmd.Run(); err != nil {
313			t.Fatalf("init through dir symlink: %v (%s)", err, se.String())
314		}
315		var out map[string]any
316		if err := json.Unmarshal(so.Bytes(), &out); err != nil || out["status"] != "initialized" {
317			t.Fatalf("init stdout=%q", so.String())
318		}
319		if _, err := os.Stat(realPath); err != nil {
320			t.Fatalf("ledger must be created inside the real directory: %v", err)
321		}
322	
323		// 经符号链接路径付款。
324		submit := exec.Command(bin, "submit", "-l", linkPath)
325		submit.Stdin = bytes.NewReader([]byte(`{"fee_bps":0,"intents":[
326		  {"id":"p1","account":"aa","asset":"usdc","amount":300}]}`))
327		if submitOut, err := submit.CombinedOutput(); err != nil {
328			t.Fatalf("submit: %v %s", err, submitOut)
329		}
330		// 经真实路径退款。
331		refund := exec.Command(bin, "refund", "-l", realPath)
332		refund.Stdin = bytes.NewReader([]byte(`{"refunds":[
333		  {"id":"r1","settlement_id":"p1","reason":"cancel"}]}`))
334		if refundOut, err := refund.CombinedOutput(); err != nil {
335			t.Fatalf("refund: %v %s", err, refundOut)
336		}
337	
338		for name, p := range map[string]string{"real": realPath, "link": linkPath} {
339			r := runCLIWith(t, []string{"query", "-l", p}, "")
340			if r.code != 0 {
341				t.Fatalf("query via %s: %s", name, r.err)
342			}
343			var snap struct {
344				Balances    []struct{ Balance int64 } `json:"balances"`
345				Settlements []struct{ ID string }     `json:"settlements"`
346				Refunds     []struct{ ID string }     `json:"refunds"`
347			}
348			if err := json.Unmarshal([]byte(r.out), &snap); err != nil {
349				t.Fatal(err)
350			}
351			if len(snap.Balances) != 1 || snap.Balances[0].Balance != 1000 ||
352				len(snap.Settlements) != 1 || snap.Settlements[0].ID != "p1" ||
353				len(snap.Refunds) != 1 || snap.Refunds[0].ID != "r1" {
354				t.Fatalf("via %s snapshot mismatches after submit/refund: %s", name, r.out)
355			}
356		}
357	
358		// 再次 init（任一路径）都必须拒绝，余额与历史保持不变。
359		for _, p := range []string{realPath, linkPath} {
360			r := runCLIWith(t, []string{"init", "-l", p}, `{"balances":[]}`)
361			if r.code != 1 || decodeOut(t, r.err)["error"].(map[string]any)["kind"] != "ledger_exists" {
362				t.Fatalf("re-init via %s: code=%d err=%s", p, r.code, r.err)
363			}
364		}
365		r := runCLIWith(t, []string{"query", "-l", realPath}, "")
366		var snap struct {
367			Balances []struct{ Balance int64 } `json:"balances"`
368		}
369		if err := json.Unmarshal([]byte(r.out), &snap); err != nil || snap.Balances[0].Balance != 1000 {
370			t.Fatalf("rejected re-init altered the ledger: %s", r.out)
371		}
372	}
