package main

import (
	"bytes"
	"encoding/json"
	"os"
	"strings"
	"testing"
)

type cliResult struct {
	code int
	out  string
	err  string
}

func runCLIWith(t *testing.T, args []string, stdin string) cliResult {
	t.Helper()
	var out, errBuf bytes.Buffer
	code := runCLI(args, strings.NewReader(stdin), &out, &errBuf)
